observation.command:
bash -c "
echo '=== FINAL STATE ==='
docker ps --format '{{.Names}}: {{.Status}}'
echo
echo 'frontend:  http://localhost:3000        -> ' \$(curl -s -o /dev/null -w '%{http_code}' -m 10 -H 'Host: localhost' http://localhost:3000/)
echo 'api health: http://localhost:3000/api/health -> ' \$(curl -s -o /dev/null -w '%{http_code}' -m 10 -H 'Host: localhost' http://localhost:3000/api/health)
echo 'api ready:  http://localhost:3000/api/ready  -> ' \$(curl -s -o /dev/null -w '%{http_code}' -m 10 -H 'Host: localhost' http://localhost:3000/api/ready)
"
